export function LauncherCard(s){const n=s.variants.map(s=>`\n        <div class="launcher-variant">\n            <strong>${s.name}</strong> — ${s.payload}\n            <p>${s.desc}</p>\n        </div>\n    `).join(""),a=s.notableMissions.map(s=>`<li>${s}</li>`).join(""),l=s.achievements.map(s=>`<li>${s}</li>`).join("");return`\n        <div class="launcher-card" style="--launcher-color: ${s.color}">\n            <div class="launcher-card-header" style="background: ${s.color}">\n                <div class="launcher-icon">${s.name[0]}</div>\n                <div>\n                    <h3>${s.fullName}</h3>\n                    <p class="launcher-type">${s.type}</p>\n                </div>\n            </div>\n            <div class="launcher-card-body">\n                <div class="launcher-stats-grid">\n                    <div class="launcher-stat">\n                        <span class="ls-label">Height</span>\n                        <span class="ls-value">${s.height}</span>\n                    </div>\n                    <div class="launcher-stat">\n                        <span class="ls-label">Mass</span>\n                        <span class="ls-value">${s.mass}</span>\n                    </div>\n                    <div class="launcher-stat">\n                        <span class="ls-label">Total Launches</span>\n                        <span class="ls-value">${s.totalLaunches}</span>\n                    </div>\n                    <div class="launcher-stat">\n                        <span class="ls-label">Success Rate</span>\n                        <span class="ls-value">${s.successRate}</span>\n                    </div>\n                    <div class="launcher-stat">\n                        <span class="ls-label">First Flight</span>\n                        <span class="ls-value">${s.firstFlight}</span>\n                    </div>\n                    <div class="launcher-stat">\n                        <span class="ls-label">Stages</span>\n                        <span class="ls-value">${s.stages}</span>\n                    </div>\n                </div>\n                <p class="launcher-description">${s.description}</p>\n                <div class="launcher-section">\n                    <h4>Variants</h4>\n                    <div class="launcher-variants">${n}</div>\n                </div>\n                <div class="launcher-section">\n                    <h4>Notable Missions</h4>\n                    <ul>${a}</ul>\n                </div>\n                <div class="launcher-section">\n                    <h4>Achievements</h4>\n                    <ul>${l}</ul>\n                </div>\n            </div>\n        </div>\n    `}